{"command": "cat > /prediction.json << 'EOF'
{
    "vllm/model_executor/layers/rotary_embedding/mrope.py": {
        "_triton_mrope_forward": "@triton.jit\ndef _triton_mrope_forward(\n    q_ptr,\n    k_ptr,\n    cos,\n    sin,\n    num_tokens,\n    n_qh: tl.constexpr,\n    n_kh: tl.constexpr,\n    hd: tl.constexpr,\n    rd: tl.constexpr,\n    pad_n_qh: tl.constexpr,\n    pad_n_kh: tl.constexpr,\n    pad_hd: tl.constexpr,\n    mrope_section_t: tl.constexpr,\n    mrope_section_h: tl.constexpr,\n    mrope_section_w: tl.constexpr,\n    is_interleaved: tl.constexpr,\n):\n    \"\"\"Triton kernel for MRoPE with support for interleaved layout.\n    \n    Args:\n        q_ptr: pointer to query tensor [num_tokens, n_qh * hd]\n        k_ptr: pointer to key tensor [num_tokens, n_kh * hd]\n        cos: cosine cache [3, num_tokens, rd // 2]\n        sin: sine cache [3, num_tokens, rd // 2]\n        num_tokens: number of tokens\n        n_qh: number of query heads\n        n_kh: number of key heads\n        hd: head dimension\n        rd: rotary dimension (<= hd)\n        pad_n_qh: padded n_qh (power of 2)\n        pad_n_kh: padded n_kh (power of 2)\n        pad_hd: padded hd (power of 2)\n        mrope_section_t: size of T section\n        mrope_section_h: size of H section\n        mrope_section_w: size of W section\n        is_interleaved: whether to use interleaved layout\n    \"\"\"\n    pid = tl.program_id(0)\n    # locate start address for this token\n    q_ptr = q_ptr + pid * (n_qh * hd)\n    k_ptr = k_ptr + pid * (n_kh * hd)\n    \n    half_rd = rd // 2\n    \n    # Get pointers to T, H, W cos/sin for this token\n    # cos and sin have shape [3, num_tokens, half_rd]\n    # Layout: [T values, H values, W values] for each token\n    t_cos = cos + pid * half_rd\n    h_cos = t_cos + num_tokens * half_rd\n    w_cos = h_cos + num_tokens * half_rd\n    t_sin = sin + pid * half_rd\n    h_sin = t_sin + num_tokens * half_rd\n    w_sin = h_sin + num_tokens * half_rd\n    \n    # Create offset array for half rotary dimension\n    cos_offsets = tl.arange(0, pad_hd // 2)\n    \n    if not is_interleaved:\n        # Non-interleaved: T values in first section, H in second, W in third\n        # This matches _triton_qwen2vl_mrope_forward\n        t_end = mrope_section_t\n        h_end = t_end + mrope_section_h\n        w_end = half_rd  # t_end + mrope_section_h + mrope_section_w\n        \n        t_mask = cos_offsets < t_end\n        h_mask = (t_end <= cos_offsets) & (cos_offsets < h_end)\n        w_mask = (h_end <= cos_offsets) & (cos_offsets < w_end)\n        \n        t_cos_row = tl.load(t_cos + cos_offsets, mask=t_mask, other=0)\n        h_cos_row = tl.load(h_cos + cos_offsets, mask=h_mask, other=0)\n        w_cos_row = tl.load(w_cos + cos_offsets, mask=w_mask, other=0)\n        t_sin_row = tl.load(t_sin + cos_offsets, mask=t_mask, other=0)\n        h_sin_row = tl.load(h_sin + cos_offsets, mask=h_mask, other=0)\n        w_sin_row = tl.load(w_sin + cos_offsets, mask=w_mask, other=0)\n        \n        cos_row = t_cos_row + h_cos_row + w_cos_row\n        sin_row = t_sin_row + h_sin_row + w_sin_row\n    else:\n        # Interleaved: implement apply_interleaved_rope logic\n        # x_t = x[0].clone()\n        # x_t[..., 1:mrope_section[1] * 3:3] = x[1, ..., 1:mrope_section[1] * 3:3]\n        # x_t[..., 2:mrope_section[2] * 3:3] = x[2, ..., 2:mrope_section[2] * 3:3]\n        \n        # Start with T values (x[0])\n        cos_row = tl.load(t_cos + cos_offsets)\n        sin_row = tl.load(t_sin + cos_offsets)\n        \n        # Override with H values at positions 1, 4, 7, ... (every 3rd starting from 1)\n        # up to mrope_section_h * 3\n        h_positions = tl.arange(0, pad_hd // 2)\n        h_mask = (h_positions % 3 == 1) & (h_positions < mrope_section_h * 3) & (h_positions < half_rd)\n        \n        # H values are stored at positions 1, 4, 7, ... in h_cos/h_sin\n        # So we load from the same offset\n        h_cos_vals = tl.load(h_cos + h_positions, mask=h_mask, other=0)\n        h_sin_vals = tl.load(h_sin + h_positions, mask=h_mask, other=0)\n        \n        # Override cos_row/sin_row at H positions\n        cos_row = tl.where(h_mask, h_cos_vals, cos_row)\n        sin_row = tl.where(h_mask, h_sin_vals, sin_row)\n        \n        # Override with W values at positions 2, 5, 8, ... (every 3rd starting from 2)\n        # up to mrope_section_w * 3\n        w_positions = tl.arange(0, pad_hd // 2)\n        w_mask = (w_positions % 3 == 2) & (w_positions < mrope_section_w * 3) & (w_positions < half_rd)\n        \n        w_cos_vals = tl.load(w_cos + w_positions, mask=w_mask, other=0)\n        w_sin_vals = tl.load(w_sin + w_positions, mask=w_mask, other=0)\n        \n        cos_row = tl.where(w_mask, w_cos_vals, cos_row)\n        sin_row = tl.where(w_mask, w_sin_vals, sin_row)\n    \n    # Now apply rotary embedding to q and k\n    # left half of the head\n    first_half_q_offsets = tl.arange(0, pad_n_qh)[:, None] * hd + tl.arange(\n        0, pad_hd // 2)[None, :]\n    first_half_k_offsets = tl.arange(0, pad_n_kh)[:, None] * hd + tl.arange(\n        0, pad_hd // 2)[None, :]\n    first_q_mask = (tl.arange(0, pad_n_qh)[:, None] < n_qh) & (tl.arange(\n        0, pad_hd // 2)[None, :] < rd // 2)\n    first_k_mask = (tl.arange(0, pad_n_kh)[:, None] < n_kh) & (tl.arange(\n        0, pad_hd // 2)[None, :] < rd // 2)\n\n    q_tile_1 = tl.load(q_ptr + first_half_q_offsets,\n                       mask=first_q_mask,\n                       other=0).to(sin_row.dtype)\n    k_tile_1 = tl.load(k_ptr + first_half_k_offsets,\n                       mask=first_k_mask,\n                       other=0).to(sin_row.dtype)\n\n    # right half of the head\n    second_half_q_offsets = first_half_q_offsets + (rd // 2)\n    second_half_k_offsets = first_half_k_offsets + (rd // 2)\n    second_q_mask = first_q_mask\n    second_k_mask = first_k_mask\n\n    q_tile_2 = tl.load(q_ptr + second_half_q_offsets,\n                       mask=second_q_mask,\n                       other=0).to(sin_row.dtype)\n    k_tile_2 = tl.load(k_ptr + second_half_k_offsets,\n                       mask=second_k_mask,\n                       other=0).to(sin_row.dtype)\n\n    # Apply rotary embedding: y = [x1, x2] * [cos, cos] + [-x2, x1] * [sin, sin]\n    new_q_tile_1 = q_tile_1 * cos_row - q_tile_2 * sin_row\n    tl.store(q_ptr + first_half_q_offsets, new_q_tile_1, mask=first_q_mask)\n    new_q_tile_2 = q_tile_2 * cos_row + q_tile_1 * sin_row\n    tl.store(q_ptr + second_half_q_offsets, new_q_tile_2, mask=second_q_mask)\n\n    new_k_tile_1 = k_tile_1 * cos_row - k_tile_2 * sin_row\n    tl.store(k_ptr + first_half_k_offsets, new_k_tile_1, mask=first_k_mask)\n    new_k_tile_2 = k_tile_2 * cos_row + k_tile_1 * sin_row\n    tl.store(k_ptr + second_half_k_offsets, new_k_tile_2, mask=second_k_mask)"
    }
}
EOF"}

